def car_race_collision(n: int):
    collisions = 0
    positions = list(range(n))
    for i in range(n):
        for j in range(n):
            if i != j and positions[i] + positions[j] == n - 1:
                collisions += 1
                positions[j] += 1  # continue moving the car
    return collisions

