def strange_sort_list(lst):
    if not lst:
        return []

    result = []
    min_val = float('inf')
    max_val = float('-inf')
    found_min = False
    found_max = False

    for num in sorted(lst):
        if (found_min and not found_max) or (not found_min and not found_max):
            if found_min:
                max_val = num
                found_max = True
            else:
                min_val = num
                found_min = True
        else:
            if found_min and found_max:
                if num > min_val:
                    result.append(min_val)
                    min_val = num
                elif num < max_val:
                    result.append(max_val)
                    max_val = num
                else:
                    result.append(num)
            elif found_min:
                result.append(min_val)
                min_val = num
            else:
                result.append(max_val)
                max_val = num

    # Add any remaining values
    if found_min:
        result.append(min_val)
    if found_max:
        result.append(max_val)

    return result

