def encrypt(s):
    result = ""
    for char in s:
        if char.isalpha():
            ascii_offset = 97 if char.islower() else 65
            encrypted_char = chr((ord(char) - ascii_offset + 2 * 2) % 26 + ascii_offset)
            result += encrypted_char
        else:
            result += char
    return result

def encrypt(s):
    # Create a dictionary mapping original alphabet to shifted alphabet
    shift = 2 * 2
    shifted_alphabet = 'abcdefghijklmnopqrstuvwxyz'
    shifted_alphabet += shifted_alphabet  # Add the entire alphabet again
    mapping = {original: shifted for original, shifted in zip(shifted_alphabet, shifted_alphabet[shift:])}

    # Encrypt each character in the string
    encrypted_string = ''
    for char in s:
        if char.isalpha():
            if char.isupper():
                encrypted_char = mapping[char.lower()] if char.lower() in mapping else char
                encrypted_string += encrypted_char.upper()
            else:
                encrypted_string += mapping[char]
        else:
            encrypted_string += char

    return encrypted_string

