import math

def closest_integer(value):
    try:
        num = float(value)
    except ValueError:
        raise ValueError("Invalid input. Please enter a number.")

    integer_part = math.floor(abs(num))
    decimal_part = abs(num) - integer_part

    if decimal_part < 0.5:
        return int(num)
    else:
        return int(math.ceil(abs(num))) * math.copysign(1, num)

