import re

def file_name_check(file_name):
    # Check if the string is empty
    if not file_name:
        return 'No'

    # Check if the string starts with a letter
    if not re.match('^[a-zA-Z]', file_name):
        return 'No'

    # Count the number of digits in the string
    if len(re.findall('\d', file_name)) > 3:
        return 'No'

    # Check if there's exactly one dot in the string
    if file_name.count('.') != 1:
        return 'No'

    # Check the substring after the dot
    if file_name.split('.')[-1] not in ['txt', 'exe', 'dll']:
        return 'No'

    return 'Yes'

