def int_to_mini_roman(number):
    if not 1 <= number <= 1000:
        raise ValueError("Number must be between 1 and 1000")

    roman_numerals = {
        1000: 'm', 900: 'cm', 500: 'd', 400: 'cd',
        100: 'c', 90: 'xc', 50: 'l', 40: 'xl',
        10: 'x', 9: 'ix', 5: 'v', 4: 'iv', 1: 'i'
    }

    result = ''
    for value, numeral in roman_numerals.items():
        while number >= value:
            result += numeral
            number -= value
    return result

# Test cases
assert int_to_mini_roman(19) == 'xix'
assert int_to_mini_roman(152) == 'clii'
assert int_to_mini_roman(426) == 'cdxxvi'

def int_to_mini_roman(number):
    if not isinstance(number, int) or number < 1 or number > 1000:
        raise ValueError("Input must be an integer between 1 and 1000")

    val = [
        1000, 900, 500, 400,
        100, 90, 50, 40,
        10, 9, 5, 4,
        1
        ]
    syb = [
        "M", "CM", "D", "CD",
        "C", "XC", "L", "XL",
        "X", "IX", "V", "IV",
        "I"
        ]
    roman_num = ''
    i = 0
    while  number > 0:
        for _ in range(number // val[i]):
            roman_num += syb[i]
            number -= val[i]
        i += 1
    return roman_num.lower()

def find_max(words):
    max_word = ""
    max_unique_chars = 0
    for word in words:
        unique_chars = len(set(word))
        if unique_chars > max_unique_chars:
            max_unique_chars = unique_chars
            max_word = word
        elif unique_chars == max_unique_chars:
            if word < max_word:
                max_word = word
    return max_word

def find_max(words):
    max_word = max(words, key=lambda word: (len(set(word)), -ord(word[0])))
    return max_word

def find_max(words):
    max_word = ""
    max_unique_chars = 0
    for word in words:
        unique_chars = set(word)
        if len(unique_chars) > max_unique_chars:
            max_word = word
            max_unique_chars = len(unique_chars)
        elif len(unique_chars) == max_unique_chars:
            max_word = min(max_word, word)
    return max_word

def do_algebra(operator, operand):
    # Check if the lengths of the operator and operand lists are valid
    if len(operator) != len(operand) - 1:
        return "Invalid input: The length of operator list must be equal to the length of operand list minus one."

    # Initialize the result with the first operand
    result = operand[0]

    # Iterate over the operators and operands
    for op, num in zip(operator, operand[1:]):
        # Perform the operation based on the operator
        if op == '+':
            result += num
        elif op == '-':
            result -= num
        elif op == '*':
            result *= num
        elif op == '/':
            # Check for division by zero
            if num == 0:
                return "Invalid input: Division by zero."
            result /= num
        elif op == '//':
            # Check for division by zero
            if num == 0:
                return "Invalid input: Division by zero."
            result //= num
        elif op == '**':
            result **= num
        else:
            return "Invalid operator: Only +, -, *, /, //, ** are allowed."

    return result

# Test the function
print(do_algebra(['+', '*', '-'], [2, 3, 4, 5]))  # Output: 9
print(do_algebra(['+', '*'], [10, 3, 4]))  # Output: 68
print(do_algebra(['*', '+'], [10, 3, 4]))  # Output: 47

def solve(s):
    result = ""
    all_letters = True
    for char in s:
        if char.isalpha():
            result += char.swapcase()
        else:
            result += char
            all_letters = False
    if all_letters:
        return result[::-1]
    return result

# Test cases
print(solve("1234"))  # Output: "4321"
print(solve("ab"))  # Output: "AB"
print(solve("#a@C"))  # Output: "#A@c"

def solve(s):
    result = []
    for char in s:
        if char.isalpha():
            if char.isupper():
                result.append(char.lower())
            else:
                result.append(char.upper())
        else:
            result.append(char)
    if not any(char.isalpha() for char in result):
        result = result[::-1]
    return ''.join(result)

# Test the function
print(solve("1234"))  # Outputs: "4321"
print(solve("ab"))    # Outputs: "AB"
print(solve("#a@C"))  # Outputs: "#A@c"

